import javax.swing.*;import java.awt.*;
/** FAQ and support details view; its text is maintained centrally in HelpContent. */
public final class HelpPanel extends JPanel {
    public HelpPanel(){super(new BorderLayout());JTabbedPane tabs=new JTabbedPane();tabs.addTab("FAQs",faqs());tabs.addTab("Contact Details",contactDetails());add(tabs,BorderLayout.CENTER);}
    private JComponent faqs(){JPanel list=new JPanel();list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));list.setBorder(UIStyleUtility.compactModuleBorder());for(String[] faq:HelpContent.FAQS){JButton question=new JButton(faq[0]);question.setAlignmentX(Component.LEFT_ALIGNMENT);question.setHorizontalAlignment(SwingConstants.LEFT);JTextArea answer=new JTextArea(faq[1]);answer.setEditable(false);answer.setLineWrap(true);answer.setWrapStyleWord(true);answer.setOpaque(false);answer.setVisible(false);answer.setBorder(BorderFactory.createEmptyBorder(6,16,10,16));question.addActionListener(e->{answer.setVisible(!answer.isVisible());list.revalidate();list.repaint();});list.add(question);list.add(answer);}return new JScrollPane(list);}
    private JComponent contactDetails(){JPanel panel=new JPanel(new GridBagLayout());panel.setBorder(UIStyleUtility.compactModuleBorder());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(8,8,8,8);c.anchor=GridBagConstraints.NORTHWEST;for(int row=0;row<HelpContent.CONTACT_DETAILS.length;row++){c.gridx=0;c.gridy=row;panel.add(new JLabel(HelpContent.CONTACT_DETAILS[row][0]+":"),c);c.gridx=1;c.weightx=1;c.fill=GridBagConstraints.HORIZONTAL;JTextArea value=new JTextArea(HelpContent.CONTACT_DETAILS[row][1]);value.setEditable(false);value.setLineWrap(true);value.setWrapStyleWord(true);panel.add(value,c);}return new JScrollPane(panel);}
}
